  const [perlinTexture, noiseTexture] = await Promise.all([
    this._loadSharedTexture(perlinTextureUrl, this._prepareRepeatTexture),
    this._loadSharedTexture(noiseTextureUrl, this._prepareRepeatTexture),
  ]);
  this._createMouseTexture(); // Runtime DataTexture
}

private _createMouseTexture(): void {
  this._mouseTextureData = new Float32Array(...);
  this._mouseTexture = new THREE.DataTexture(
    this._mouseTextureData,
    CLOUD_MOUSE_TEXTURE_SIZE,
    CLOUD_MOUSE_TEXTURE_SIZE,
    THREE.RGBAFormat,
    THREE.FloatType,
  );
}
```

