## 7. SceneObject Base Class (Inferred Pattern)

All objects inherit from `SceneObject<TweenProps>` with these methods:

```typescript
export class SomeObject extends SceneObject<SomeTweenProps> {
  // Lifecycle
  override async runObject(): Promise<void> { /* setup */ }
  override runUpdate(deltaTime: number): void { /* animation */ }
  override dispose(): void { /* cleanup */ }

  // Configuration
  setOptions(props: Partial<Options>): this { /* merge config */ }
  protected override getOptions(): Record<string, unknown>
  protected override syncFromOptions(): void { /* apply config to Three.js objects */ }

  // Animation targets
  override getAnimationTarget(): THREE.Object3D | null
  override getTweenApplyMode(): "mergeAndSync" | "replace"

  // Helpers
  protected ensureTimelineRoot(name: string): THREE.Group | null
  protected attachToTimelineRoot(obj: THREE.Object3D, name: string): void
  protected getTimelineRoot(): THREE.Object3D | null
  protected applyVisibility(visible: boolean): void
  protected resolveAssetPath(url: string): string
}
```

