import type { AppBootstrapRuntime } from "../types/app.types.js";
import { TimelineRuntime } from "../runtime/TimelineRuntime.js";
import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";

export class AppBootstrap {
  private static _runtime: AppBootstrapRuntime | null = null;
  private static readonly _pageRootSelector = 'main[data-page]';

  static async init(): Promise<void> {
    ResponsiveRuntime.getDefault().init();
    if (!AppBootstrap._runtime) {
      AppBootstrap._runtime = await AppBootstrap._createRuntime();
    }
    const runtime = AppBootstrap._runtime;
    await runtime.lenisRuntime.init();

    const initialContainer = document.querySelector<HTMLElement>(
      AppBootstrap._pageRootSelector,
    );
    await runtime.pageRuntime.runPage(initialContainer ?? undefined);
  }

  static dispose(): void {
    const runtime = AppBootstrap._runtime;
    if (!runtime) return;
    runtime.lenisRuntime.dispose();
    runtime.pageRuntime.dispose();
    ResponsiveRuntime.resetDefault();
    TimelineRuntime.clear();
    AppBootstrap._runtime = null;
  }

  private static async _createRuntime(): Promise<AppBootstrapRuntime> {
    const [
      pageRuntimeModule,
      lenisRuntimeModule,
    ] = await Promise.all([
      import("../runtime/PageRuntime.js"),
      import("../lib/lenis/LenisRuntime.js"),
    ]);

    const pageRuntime = new pageRuntimeModule.PageRuntime();
    const lenisRuntime = new lenisRuntimeModule.LenisRuntime();

    return {
      pageRuntime,
      lenisRuntime,
    };
  }
}

