export class PageRuntime {
  private controller: PageController | null = null;
  private bootTask: Promise<void> | null = null;
  private readonly _globalUiRuntime = new PageGlobalUiRuntime();
  private readonly _featureCardCanvasRuntime = new FeatureCardCanvasRuntime();
  private readonly _subpageStarfieldRuntime = new SubpageStarfieldRuntime();

  async runPage(root?: HTMLElement): Promise<void> {
    if (this.bootTask) return this.bootTask;

    this.bootTask = (async () => {
      this._disposePageRuntime();
      this.disposeController();

      if ("scrollRestoration" in history) {
        history.scrollRestoration = "manual";
      }
      window.scrollTo({ top: 0, behavior: "auto" });

      this._globalUiRuntime.init(root);
      this._featureCardCanvasRuntime.init(root);
      this._subpageStarfieldRuntime.init(root);

      this.controller = new PageController();
      await this.controller.init(root);
    })().finally(() => {
      this.bootTask = null;
    });

    return this.bootTask;
  }

  syncAfterContainerChange(): void {
    this._globalUiRuntime.syncAfterContainerChange();
  }

  disposeController(): void {
    this.controller?.dispose();
    this.controller = null;
    this.bootTask = null;
    TimelineRuntime.clear();
  }

  dispose(): void {
    this.disposeController();
    this._disposePageRuntime();
    TimelineRuntime.clear();
  }

  private _disposePageRuntime(): void {
    try {
      this._globalUiRuntime.dispose();
    } catch (error) {
      console.warn(
        "[PageRuntime._disposePageRuntime] Global UI cleanup failed.",
        error,
      );
    }
    try {
      this._featureCardCanvasRuntime.dispose();
    } catch (error) {
      console.warn(
        "[PageRuntime._disposePageRuntime] Feature card canvas cleanup failed.",
        error,
      );
    }
    try {
      this._subpageStarfieldRuntime.dispose();
    } catch (error) {
      console.warn(
        "[PageRuntime._disposePageRuntime] Subpage starfield cleanup failed.",
        error,
      );
    }
  }

