export { type EnvCheckResult } from "../types/core.types.js";

export class EnvSetup {
  private static readPageTypeFrom(el: Element | null): string | undefined {
    if (!el || !(el instanceof HTMLElement)) return undefined;
    return el.dataset.page;
  }

  static getPageType(root?: ParentNode | null): string {
    const container = EnvSetup._resolvePageContainer(root);
    return (
      EnvSetup.readPageTypeFrom(container) ??
      (root instanceof HTMLElement ? root.dataset.barbaNamespace : undefined) ??
      document.body?.dataset.page ??
      pageMain
    );
  }

  static getQueryParam(key: string): string | null {
    if (typeof window === "undefined") return null;
    try {
      const params = new URLSearchParams(window.location.search);
      return params.get(key);
    } catch (error) {
      console.warn("[EnvSetup.getQueryParam] Failed to parse query params.", error);
      return null;
    }
  }

  static hasQueryFlag(key: string, expectedValue: string): boolean {
    return EnvSetup.getQueryParam(key) === expectedValue;
  }

  static checkWebGL(): boolean {
    try {
      const canvas = document.createElement("canvas");
      return !!(
        canvas.getContext("webgl") || canvas.getContext("experimental-webgl")
      );
    } catch (error) {
      return false;
    }
