static shouldInit(options: EnvInitOptions): EnvCheckResult {
  const pageType = EnvSetup.getPageType(options.root);
  const allowed = options.allowedPageTypes;
  if (allowed && !allowed.has(pageType)) {
    return {
      shouldInit: false,
      pageType,
      reason: "page type is not allowed",
    };
  }
  if (!EnvSetup.checkWebGL()) {
    return {
      shouldInit: false,
      pageType,
      reason: "webgl is not available",
    };
  }
  if (!EnvSetup.checkCanvas(options.canvasId, options.root)) {
    return {
      shouldInit: false,
      pageType,
      reason: "canvas host was not found",
    };
  }
  return { shouldInit: true, pageType };
}

private static _resolvePageContainer(root?: ParentNode | null): HTMLElement | null {
  if (root instanceof HTMLElement) {
    if (root.matches("main[data-page]")) {
      return root;
    }
    return root.querySelector<HTMLElement>("main[data-page]");
  }
  if (root) {
    return root.querySelector<HTMLElement>("main[data-page]");
  }
  return (
    document.querySelector<HTMLElement>("main[data-page]") ??
    document.getElementById("main")

