&-proof {
  width: 100%;

  &__body {
    width: 100%;
    background: rgba(0, 0, 0, 0.24);
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
  }

  &__txt {
    display: flex;
    flex-direction: column;
    gap: var(--gutter-md);
    margin-bottom: var(--gutter-2xl);

    p {
      max-width: fluid(480, 640);
      color: var(--clr-text-body);
    }
  }

  &__grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: var(--gutter-md);
    perspective: 1200px;
    perspective-origin: 50% 30%;

    @include mq(lg) {
      grid-template-columns: repeat(2, 1fr);
    }

    @include mq(sm) {
      grid-template-columns: 1fr;
    }
  }

  &__card {
    position: relative;
    --corner-panel-padding: fluid(20, 32);
    --corner-panel-border: var(--clr-border-weak);
    --corner-panel-border-hover: var(--clr-border-default);
    --corner-panel-background: transparent;
    --corner-panel-background-hover: color-mix(
      in srgb,
      var(--clr-border-weak) 12%,
      transparent
    );
    --corner-panel-corner: var(--clr-border-strong);
    --corner-panel-corner-hover: var(--clr-text-desc);
    --corner-panel-hover-offset-y: 0px;

    // 초기: Z축 뒤에 숨김
    opacity: 0;
    transform: translateZ(-80px) scale(0.88);
  }

  // 섹션이 씬 시스템에 의해 보여질 때 (aria-hidden="false") 카드 진입 애니메이션 실행
  &[aria-hidden="false"] &__card {
    animation: no-proof-card-enter 0.72s cubic-bezier(0.22, 1, 0.36, 1)
      forwards;
    animation-delay: var(--proof-card-delay, 0s);
  }

  &__card-inner {
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    height: 100%;
  }

  &__card-category {
    color: var(--clr-text-desc);
    font-family: var(--family-ui);
    letter-spacing: 0.06em;
  }

  &__card-label {
    margin-top: var(--gutter-sm);
    font-family: var(--family-en-title);
    line-height: 0.92;
  }

  &__card-proof {
    margin-top: auto;
    padding-top: var(--gutter-md);
    color: var(--clr-text-body);
    border-top: 1px solid
      color-mix(in srgb, var(--clr-border-weak) 60%, transparent);
  }
}

